class Solution {
public:
    string countAndSay(int n) {
        if(n==1)return "1";
        string s=countAndSay(n-1);
        string b="";
        int c=0;
        for(int i=0;i<s.size();i++){
            c++;
            if(i==s.size()-1||s[i]!=s[i+1]){
                b+=c+48;
                b+=s[i];
                c=0;
            }
        }
        return b;
    }
};

