class Solution {
public:
    bool isNumber(span<char> s) {
        if (s[0] == '+' || s[0] == '-') s = s.subspan(1);

        auto s_ = strip_int(s);

        if (s_[0] == '.') {
            bool empty_before_dot = s_.size() == s.size();
            s = s_.subspan(1);
            s_ = strip_int(s);
            if (empty_before_dot && s_.size() == s.size()) return false;
        } else if (s_.size() == s.size()) return false;

        if (s_.empty()) return true;
        if (s_[0] == 'e' || s_[0] == 'E') {
            s = s_.subspan(1);
            if (!s.empty() && (s[0] == '+' || s[0] == '-')) s = s.subspan(1);
            s_ = strip_int(s);
            if (s_.size() == s.size()) return false;
        }

        return s_.empty();
    }

    span<char> strip_int(span<char> s) {
        size_t i = 0;

        while (i < s.size() && is_digit(s[i])) ++i;

        return s.subspan(i);
    }

    bool is_digit(char c) {
        return isdigit(c);
    }
};

