class Solution {
public:
    void tereversal(TreeNode* node, int curr_depth, vector<vector<int>> &res) {
        if (res.size() <= curr_depth) {
            res.resize(curr_depth + 1);
        }
        if (!node) {
            return;
        }
        res[curr_depth].push_back(node->val);
        tereversal(node->left, curr_depth + 1, res);
        tereversal(node->right, curr_depth + 1, res);
    }

    vector<vector<int>> zigzagLevelOrder(TreeNode* root) {
        vector<vector<int>> res;
        tereversal(root, 0, res);
        if (res.back().empty()) {
            res.pop_back();
        }
        for (int i = 1; i < res.size(); i += 2) {
            std::reverse(res[i].begin(), res[i].end());
        }
        return res;
    }
};

